const sensorGroups={1:[{name:"溫濕度感測器B",img:"../picture/sensor_temp_b.png",deviceId:"8266_2"},{name:"灰塵感測器",img:"../picture/sensor_dust.png",deviceId:"8266_3"},{name:"空氣品質感測器",img:"../picture/sensor_air.png",deviceId:"8266_3"}],2:[{name:"溫濕度感測器A",img:"../picture/sensor_temp_a.png",deviceId:"8266_4"},{name:"電力感測器",img:"../picture/sensor_power.png",deviceId:"8266_5"}]};async function checkSensorStatus(e){try{const n=await fetch("http://192.168.3.85:9090/allData/allSenosrData");if(!n.ok)return!1;const s=await n.json();for(const n in s){const r=s[n];if(Array.isArray(r)){if(r.find(n=>n.deviceId===e))return!0}}return!1}catch(e){return console.error("無法取得感測器 API 資料:",e),!1}}async function showGroup(e){const n=document.getElementById("layout-container"),s=document.getElementById("sensor-details"),r=sensorGroups[e];if(!s||!r)return;n&&n.classList.remove("is-centered"),s.innerHTML='<div style="font-size:20px; font-weight:bold; color:#666;">載入感測器狀態中...</div>';const t=await Promise.all(r.map(async e=>{const n=await checkSensorStatus(e.deviceId),s=n?"狀態：已啟動":"狀態：未啟動",r=n?"color: #2e7d32;":"color: #d32f2f;";return`\n                <div class="sensor-card">\n                    <img src="${e.img}" alt="${e.name}" onerror="this.src='../picture/sensorplace.png'">\n                    <h3>${e.name}</h3>\n                    <p class="status" style="${r}">${s}</p>\n                </div>\n            `}));s.innerHTML=`<div class="card-list">${t.join("")}</div>`}